// Mandodari: a leather puppet in profile, drawn facing left (flipped to face Ravana). Braid and bun behind, hands raised in plea.
Object.assign(W, {
  mandodari(cls) {
    const O = W.O, back = 'color-mix(in srgb, var(--skinM) 76%, var(--ink))';
    let bun = '';
    for (let i = 0; i < 9; i++) { const a = i / 9 * Math.PI * 2; bun += '<circle cx="' + (60 + Math.cos(a) * 30).toFixed(1) + '" cy="' + (-768 + Math.sin(a) * 30).toFixed(1) + '" r="6" style="fill:var(--second)"/>'; }
    return '<g class="' + cls + '">' +
      '<path d="M-104 -590 L-60 900" style="stroke:var(--ink);stroke-width:4"/>' +
      '<path d="M34 -790 Q98 -760 88 -690 Q106 -600 88 -470 Q72 -454 60 -474 Q76 -600 56 -680 Q44 -722 20 -738 Z" style="fill:var(--ink)"/>' + W.lace(78, -680, 74, -500, 5, 5) +
      '<circle cx="60" cy="-768" r="32" style="fill:var(--ink)"/>' + bun +
      '<path d="M36 -612 L64 -598 L40 -500 L14 -508 Z M14 -508 L40 -500 L-96 -576 L-108 -598 Z" style="fill:' + back + ';' + O + '"/>' +
      '<path d="M-72 -446 L72 -446 L112 0 L-124 0 Z" style="fill:var(--red);' + O + '"/>' +
      '<path d="M-30 -440 L-50 -40 M8 -440 L4 -40 M40 -440 L66 -40" style="stroke:var(--redDeep);stroke-width:5;fill:none"/>' +
      '<path d="M-120 -44 L110 -44 L112 0 L-124 0 Z" style="fill:var(--gold);' + O + '"/>' + W.lace(-112, -22, 104, -22, 16, 4) +
      '<path d="M-64 -506 L62 -506 L68 -440 L-68 -440 Z" style="fill:var(--skinM);' + O + '"/>' +
      '<path d="M-68 -646 Q-80 -566 -70 -500 L66 -500 Q74 -566 56 -646 Z" style="fill:var(--goldDeep);' + O + '"/>' + W.lace(-60, -520, 60, -520, 10, 3.5) +
      '<path d="M56 -646 Q0 -566 -62 -470 L-40 -454 Q12 -540 82 -604 Q112 -560 122 -420 L142 -432 Q128 -604 56 -646 Z" style="fill:var(--red);' + O + '"/>' + W.lace(-50, -470, 50, -628, 9, 3.5) + W.lace(92, -590, 132, -436, 7, 3.5) +
      '<path d="M-36 -686 L18 -686 L26 -640 L-40 -640 Z" style="fill:var(--skinM);' + O + '"/><path d="M-52 -648 Q-8 -602 42 -648" style="fill:none;stroke:var(--gold);stroke-width:9"/>' + W.lace(-40, -634, 30, -634, 6, 3) +
      '<g class="' + cls + '-head">' +
      '<path d="M46 -800 Q-22 -818 -56 -790 L-64 -762 L-86 -744 Q-82 -735 -71 -733 L-66 -722 Q-30 -711 10 -704 L40 -714 Q64 -752 46 -800 Z" style="fill:var(--skinM);' + O + '"/>' +
      '<g class="' + cls + '-jaw"><path d="M-66 -722 Q-73 -712 -67 -702 Q-70 -690 -58 -683 Q-30 -676 0 -689 L20 -712 Q-20 -711 -66 -722 Z" style="fill:var(--skinM);' + O + '"/><path d="M-70 -711 Q-62 -705 -52 -709" style="fill:none;stroke:var(--red);stroke-width:4;stroke-linecap:round"/></g>' +
      '<path d="M-75 -717 Q-66 -723 -57 -717" style="fill:none;stroke:var(--red);stroke-width:4;stroke-linecap:round"/>' +
      '<path d="M-58 -758 Q-42 -772 -24 -760 Q-42 -748 -58 -758 Z" style="fill:var(--second);' + O + '"/><circle cx="-41" cy="-759" r="6" style="fill:var(--ink)"/>' +
      '<path d="M-62 -758 Q-42 -777 -18 -762 L-2 -768" style="fill:none;stroke:var(--ink);stroke-width:3.5"/>' +
      '<path d="M-64 -773 Q-52 -790 -20 -787" style="fill:none;stroke:var(--ink);stroke-width:5;stroke-linecap:round"/>' +
      '<circle cx="-50" cy="-795" r="6" style="fill:var(--red)"/>' +
      '<path class="' + cls + '-tear" d="M-38 -748 Q-45 -735 -38 -728 Q-31 -735 -38 -748 Z" style="fill:var(--second);opacity:0;stroke:var(--goldDeep);stroke-width:1.5"/>' +
      '<circle cx="-80" cy="-737" r="10" style="fill:none;stroke:var(--gold);stroke-width:3.5"/>' +
      '<path d="M18 -716 V-698" style="stroke:var(--gold);stroke-width:4"/><path d="M2 -684 Q18 -712 34 -684 Z" style="fill:var(--gold);' + O + '"/>' + W.lace(4, -678, 32, -678, 4, 3) +
      '<path d="M30 -800 Q60 -792 50 -748" style="fill:none;stroke:var(--ink);stroke-width:10"/>' +
      '<path d="M-60 -804 L50 -812 L48 -834 L-56 -828 Z" style="fill:var(--gold);' + O + '"/>' + W.lace(-48, -818, 42, -823, 7, 3.5) +
      '<path d="M-44 -830 L40 -834 L22 -884 L-28 -880 Z" style="fill:var(--goldDeep);' + O + '"/><circle cx="-3" cy="-896" r="13" style="fill:var(--red);' + O + '"/><circle cx="-3" cy="-856" r="8" style="fill:var(--red)"/>' +
      '<path d="M-50 -806 L-52 -800" style="stroke:var(--gold);stroke-width:4"/></g>' +
      '<g class="' + cls + '-arm"><path d="M-148 -600 L-196 900" style="stroke:var(--ink);stroke-width:4"/>' +
      '<path d="M-66 -626 L-40 -608 L-72 -508 L-98 -520 Z M-98 -520 L-72 -508 L-130 -588 L-150 -574 Z" style="fill:var(--skinM);' + O + '"/>' +
      '<path d="M-150 -574 Q-168 -606 -146 -618 Q-126 -606 -130 -588 Z" style="fill:var(--skinM);' + O + '"/><path d="M-104 -534 L-82 -546 M-112 -546 L-90 -558" style="stroke:var(--gold);stroke-width:6"/>' +
      '<ellipse cx="-56" cy="-622" rx="22" ry="16" style="fill:var(--goldDeep);' + O + '"/></g>' +
      '</g>';
  },
});
W.RIG.mandodari = { jaw: [-14, -712], arm: [-52, -616] };

kit.scene('plea', {
  init(kit) {
    this.s = W.shot(kit, {
      id: 'plea', back: '<g style="opacity:.25">' + W.lace(60, 140, 60, 960, 16, 8) + W.lace(858, 140, 858, 960, 16, 8) + '</g>',
      cast: [{ who: 'mandodari', x: 390, y: 1760, s: 1.42, flip: true }],
      cam: [1.0, 1.05, 459, 520, 470, 500],
      arm: (t, i, talk) => (talk ? 10 + 6 * Math.sin(t * 1.5) : 4 * Math.sin(t * 0.7)),
      lines: [[12.7, 14.1, 'स्वामी…', 0, 0], [14.9, 16.7, 'एक पतिव्रता का श्राप', 0, 0], [17.0, 18.8, 'किसी कवच से नहीं रुकता।', 0, 0], [19.4, 21.7, 'उसके आगे देवता भी विवश हैं।', 0, 0], [22.1, 22.9, 'फिर…', 0, 0], [23.4, 24.88, 'यह कवच आपको', 0, 0]],
    });
  },
  render(t) { this.s.render(t); },
});
